class LayerNormGRULayer(nn.Module):
    def __init__(self, hidden_units: int):
        super().__init__()
        self.hidden_units = hidden_units
        self.input_projection = nn.Linear(hidden_units, 3 * hidden_units)
        self.hidden_projection = nn.Linear(hidden_units, 3 * hidden_units)
        self.reset_norm = nn.LayerNorm(hidden_units)
        self.update_norm = nn.LayerNorm(hidden_units)
        self.candidate_norm = nn.LayerNorm(hidden_units)
        bound = hidden_units ** -0.5
        for projection in (self.input_projection, self.hidden_projection):
            nn.init.uniform_(projection.weight, -bound, bound)
            nn.init.uniform_(projection.bias, -bound, bound)

    def forward(self, inputs: torch.Tensor):
        projected = self.input_projection(inputs)
        hidden = inputs.new_zeros((inputs.size(0), self.hidden_units))
        outputs = torch.jit.annotate(list[torch.Tensor], [])
        for input_step in projected.unbind(1):
            input_reset, input_update, input_candidate = input_step.chunk(3, dim=-1)
            hidden_reset, hidden_update, hidden_candidate = self.hidden_projection(hidden).chunk(3, dim=-1)
            reset = torch.sigmoid(self.reset_norm(input_reset + hidden_reset))
            update = torch.sigmoid(self.update_norm(input_update + hidden_update))
            candidate = torch.tanh(self.candidate_norm(input_candidate + reset * hidden_candidate))
            hidden = (1.0 - update) * candidate + update * hidden
            outputs.append(hidden)
        return torch.stack(outputs, dim=1), hidden


class LayerNormGRU(nn.Module):
    def __init__(self, hidden_units: int, num_layers: int, dropout: float):
        super().__init__()
        self.layers = nn.ModuleList([
            torch.jit.script(LayerNormGRULayer(hidden_units))
            for _ in range(num_layers)
        ])
        self.inter_layer_dropout = nn.Dropout(dropout)

    def forward(self, inputs: torch.Tensor):
        output = inputs
        final_states = []
        for layer_index, layer in enumerate(self.layers):
            output, hidden = layer(output)
            final_states.append(hidden)
            if layer_index + 1 < len(self.layers):
                output = self.inter_layer_dropout(output)
        return output, torch.stack(final_states, dim=0)


